package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter360 {
    var current: Int by Delegates.observable(85) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome361 {
    data class Success(val payload: String) : Outcome361()
    data object Failure : Outcome361()
}

fun describe361(outcome: Outcome361): String = when (outcome) {
    is Outcome361.Success -> outcome.payload
    Outcome361.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked362(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
